    });

    describe("Tests des valeurs limites et calendaires", () => {

        it("doit accepter le premier jour d'un mois", () => {
            expect(validateDueDate("2026-04-01"))
                .toBe("2026-04-01");
        });

        it("doit accepter le dernier jour d'un mois de 30 jours", () => {
